#include <Cellerator/compiler/diagnostics/implement_exact_coverage_and_ownership_diagnostics_v1.hh>
namespace cellerator::compiler::diagnostics::v1 {
coverage_diagnostic diagnose_exact_coverage(const coverage_evidence&e) noexcept {if(e.failure==coverage_failure::none)return{true,e.member,"exact coverage and contribution ownership verified"};if(!e.member)return{false,0,"failure lacks member-level evidence"};switch(e.failure){case coverage_failure::omission:return{false,e.member,"member omitted from exact cover"};case coverage_failure::duplicate:return{false,e.member,"member has duplicate contributors"};case coverage_failure::wrong_role:return{false,e.member,"member assigned an incompatible contribution role"};case coverage_failure::incompatible_partial_algebra:return{false,e.member,"partial contributors use incompatible algebra"};case coverage_failure::halo_as_contributor:return{false,e.member,"halo member incorrectly owns a contribution"};case coverage_failure::canonical_recovery_failure:return{false,e.member,"member cannot recover canonical identity"};case coverage_failure::none:break;}return{false,e.member,"unknown coverage failure"};}
}
